update public.learning_paths
set
  title = 'Gender and Society',
  goal = 'Gender and Society',
  summary = 'Introduce gender as a social structure, interactional practice, identity category, and institutional system. Clarify key distinctions and show how bodies and categories are interpreted through social meanings; analyze how systems of inequality combine rather than operate separately; compare major sociological, feminist, queer, and masculinities frameworks; and study how gender norms are taught and reproduced, how classrooms, work, families, media, and everyday interaction are gendered, and how violence, health, law, global systems, research, and social change are analyzed.',
  data = $gendjson${"slug": "gender-and-society", "title": "Gender and Society", "description": "Introduce gender as a social structure, interactional practice, identity category, and institutional system. Clarify key distinctions and show how bodies and categories are interpreted through social meanings; analyze how systems of inequality combine rather than operate separately; compare major sociological, feminist, queer, and masculinities frameworks; and study how gender norms are taught and reproduced, how classrooms, work, families, media, and everyday interaction are gendered, and how violence, health, law, global systems, research, and social change are analyzed.", "topics": [{"id": "a6b5e6fc-cf7f-40b4-ad45-018b59012c09", "type": "topic", "title": "Gender, Society, and the Sociological Imagination", "description": "This opening unit frames gender as a social pattern that operates through identity, interaction, institutions, culture, and power. Students learn to move beyond individual opinion toward sociological analysis.", "children": [{"id": "83b2847a-7ad2-40af-9a59-d3ef52c9d611", "type": "subtopic", "title": "Gender as social structure", "children": [{"id": "618e5ad8-867f-429f-bb22-f0ffba27ce1b", "type": "concept", "title": "Specific terms and topics:"}, {"id": "c3ed9541-4228-40ff-9c0b-50a01d5e0b70", "type": "concept", "title": "social structure"}, {"id": "d3a13e5b-1e5f-4f32-90ef-be1c96e9643c", "type": "concept", "title": "institution"}, {"id": "cee7e285-84a7-48f6-bd31-97ec73428e7e", "type": "concept", "title": "norm"}, {"id": "84d76445-9fab-4d83-bf87-03d6f4367ca0", "type": "concept", "title": "role"}, {"id": "21b1438c-59b8-4f6e-b1ed-c9eafbf9a01b", "type": "concept", "title": "status"}, {"id": "d19409e4-a9b3-44e2-ad28-306e2a44bd54", "type": "concept", "title": "power"}, {"id": "e83a5067-19a0-4ef6-8c3a-64dbde9ac485", "type": "concept", "title": "stratification"}, {"id": "62657ac8-3221-4c30-86aa-8cc493878a5c", "type": "concept", "title": "gender order"}, {"id":